SQL_STMT_U.val:
SELECT rf.customer_id, c.name, rf.year_month, rf.sales_slip_count, rf.payment_slip_count, rf.previous_balance,
rf.standard_sales_amount, rf.standard_return_amount, rf.standard_discount_amount,
/* ===== 標準税(:4%) 税額 ===== */ CASE WHEN c.tax_category = 2 THEN CASE WHEN c.tax_rounding = 1 THEN ROUND( ( COALESCE(rf.standard_sales_amount,0) - COALESCE(rf.standard_return_amount,0) - COALESCE(rf.standard_discount_amount,0) ) * :4 / (100 + :4) , 0) WHEN c.tax_rounding = 2 THEN FLOOR( ( COALESCE(rf.standard_sales_amount,0) - COALESCE(rf.standard_return_amount,0) - COALESCE(rf.standard_discount_amount,0) ) * :4 / (100 + :4) ) ELSE FLOOR( ( COALESCE(rf.standard_sales_amount,0) - COALESCE(rf.standard_return_amount,0) - COALESCE(rf.standard_discount_amount,0) ) * :4 / (100 + :4) ) END ELSE COALESCE(rf.standard_tax_amount,0) END AS standard_tax_amount,
rf.reduced_sales_amount, rf.reduced_return_amount, rf.reduced_discount_amount,
/* ===== 軽減税(:5%) 税額 ===== */ CASE WHEN c.tax_category = 2 THEN CASE WHEN c.tax_rounding = 1 THEN ROUND( ( COALESCE(rf.reduced_sales_amount,0) - COALESCE(rf.reduced_return_amount,0) - COALESCE(rf.reduced_discount_amount,0) ) * :5 / (100 + :5) , 0) WHEN c.tax_rounding = 2 THEN FLOOR( ( COALESCE(rf.reduced_sales_amount,0) - COALESCE(rf.reduced_return_amount,0) - COALESCE(rf.reduced_discount_amount,0) ) * :5 / (100 + :5) ) ELSE FLOOR( ( COALESCE(rf.reduced_sales_amount,0) - COALESCE(rf.reduced_return_amount,0) - COALESCE(rf.reduced_discount_amount,0) ) * :5 / (100 + :5) ) END ELSE COALESCE(rf.reduced_tax_amount,0) END AS reduced_tax_amount,
rf.payment_amount, rf.current_balance,
/* ===== 集計 ===== */ SUM(COALESCE(rf.previous_balance,0)) OVER () AS total_previous_balance,
SUM( COALESCE(rf.standard_sales_amount,0) + COALESCE(rf.reduced_sales_amount,0) ) OVER () AS total_sales,
SUM( COALESCE(rf.standard_return_amount,0) + COALESCE(rf.reduced_return_amount,0) ) OVER () AS total_returns,
SUM( COALESCE(rf.standard_discount_amount,0) + COALESCE(rf.reduced_discount_amount,0) ) OVER () AS total_discounts,
/* 内税は税額合計に含めない */ SUM( CASE WHEN c.tax_category = 2 THEN 0 ELSE COALESCE(rf.standard_tax_amount,0) + COALESCE(rf.reduced_tax_amount,0) END ) OVER () AS total_tax,
SUM(COALESCE(rf.payment_amount,0)) OVER () AS total_payments, SUM(COALESCE(rf.current_balance,0)) OVER () AS total_current_balance
FROM receivables_file AS rf LEFT JOIN customer AS c ON c.id = rf.customer_id
WHERE rf.year_month = ':1' AND COALESCE(c.branch_type, 0) <> 2 AND ( (:2 = 0 AND :3 = 0) OR (rf.customer_id BETWEEN :2 AND :3) );
